package za.co.loopmanager;
import android.app.Activity;import android.content.Context;import android.content.res.ColorStateList;import android.graphics.drawable.GradientDrawable;import android.graphics.drawable.RippleDrawable;import android.view.Gravity;import android.view.View;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.LinearLayout;import android.widget.TextView;import com.google.android.material.snackbar.Snackbar;import za.co.bacy.ui.BrandFonts;import za.co.bacy.ui.InstrumentIcon;
final class AppControls {
 static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 static GradientDrawable surface(Context c,int fill,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(c,radius));return d;}
 static View action(Context c,String title,String subtitle,String icon,int fill,Runnable run){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(c,16),dp(c,15),dp(c,14),dp(c,15));row.setMinimumHeight(dp(c,64));row.setBackground(new RippleDrawable(ColorStateList.valueOf(0x24075e55),surface(c,fill,9),null));row.setFocusable(true);row.setContentDescription(title);row.setAccessibilityDelegate(new View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(View v,AccessibilityNodeInfo i){super.onInitializeAccessibilityNodeInfo(v,i);i.setClassName("android.widget.Button");}});row.setOnClickListener(v->run.run());row.addView(new InstrumentIcon(c,icon,AccountSheets.TEAL),new LinearLayout.LayoutParams(dp(c,23),dp(c,23)));LinearLayout copy=new LinearLayout(c);copy.setOrientation(LinearLayout.VERTICAL);TextView name=new TextView(c);name.setText(title);name.setTextSize(14);name.setTextColor(AccountSheets.INK);name.setTypeface(BrandFonts.sans(c,true));copy.addView(name);if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=new TextView(c);sub.setText(subtitle);sub.setTextSize(12);sub.setTextColor(AccountSheets.MUTED);sub.setTypeface(BrandFonts.sans(c,false));copy.addView(sub);}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=dp(c,12);cp.rightMargin=dp(c,7);row.addView(copy,cp);TextView arrow=new TextView(c);arrow.setText("›");arrow.setTextSize(25);arrow.setTextColor(AccountSheets.TEAL);row.addView(arrow);return row;}
 static void notice(Activity a,String message){Snackbar s=Snackbar.make(a.findViewById(android.R.id.content),message==null?"Please check your account.":message,Snackbar.LENGTH_LONG).setTextColor(0xffffffff).setActionTextColor(AccountSheets.GOLD).setTextMaxLines(4);s.setAction("Dismiss",v->s.dismiss());s.getView().setBackground(surface(a,AccountSheets.INK,9));TextView text=s.getView().findViewById(com.google.android.material.R.id.snackbar_text);if(text!=null)text.setTypeface(BrandFonts.sans(a,false));s.show();}
}
